package com.rpsbattle.tournament.scheduler;
import com.rpsbattle.tournament.domain.*;
import com.rpsbattle.tournament.persistence.*;
import com.rpsbattle.tournament.ranking.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class SwissSchedulerTest {
 @Test void liveBo1BuchholzNeverCountsAnUnplayedPairingAsADrawOrAnOpponentAlreadyPlayed(){var t=cup(4,1);assertThat(SwissScheduler.points(t).values()).allMatch(points->points==0);for(var p:t.participants)assertThat(SwissScheduler.buchholz(t,p.participantId())).isZero();var m=t.matches.getFirst();m.status=TournamentMatch.Status.RUNNING;assertThat(SwissScheduler.points(t).values()).allMatch(points->points==0);finish(t);m.status=TournamentMatch.Status.FINISHED;m.winnerParticipantId=m.participantA.participantId();m.result="WIN";assertThat(SwissScheduler.points(t).get(m.participantA.participantId())).isEqualTo(3);assertThat(SwissScheduler.buchholz(t,m.participantB.participantId())).isEqualTo(3);}
 Tournament cup(int n,int bestOf){var t=new Tournament(UUID.randomUUID().toString(),"Swiss",TournamentFormat.SWISS,Instant.now());t.bestOf=bestOf;t.status=TournamentStatus.RUNNING;t.tieBreakOrder=List.of(TieBreak.POINTS,TieBreak.BUCHHOLZ,TieBreak.WINS);for(int i=0;i<n;i++)t.participants.add(new TournamentParticipant(UUID.randomUUID().toString(),null,"","P"+i,i));t.matches.addAll(new SwissScheduler().schedule(t));return t;}
 void finish(Tournament t){for(var m:t.matches)if(m.status==TournamentMatch.Status.PENDING){m.status=TournamentMatch.Status.FINISHED;m.winnerParticipantId=m.participantA.participantId();m.result="WIN";m.finishedAt=Instant.now();}}
 @Test void twoToThirtyTwoPlayersNeverRepeatOpponentsOrByesAndCompleteStableRounds(){for(int n=2;n<=32;n++){var t=cup(n,1);for(int guard=0;guard<7&&!t.swiss.complete();guard++){finish(t);SwissScheduler.advance(t);}assertThat(t.swiss.complete()).as("roster %s",n).isTrue();assertThat(t.swiss.currentRound()).isEqualTo(t.swiss.totalRounds());var pairs=new HashSet<Set<String>>();for(var m:t.matches)assertThat(pairs.add(Set.of(m.participantA.participantId(),m.participantB.participantId()))).isTrue();assertThat(t.rounds.stream().flatMap(r->r.byeParticipantIds().stream()).distinct().count()).isEqualTo(t.rounds.stream().mapToLong(r->r.byeParticipantIds().size()).sum());for(var r:t.rounds){var ids=new HashSet<>(r.byeParticipantIds());for(var m:t.matches)if(m.round==r.number()){assertThat(ids.add(m.participantA.participantId())).isTrue();assertThat(ids.add(m.participantB.participantId())).isTrue();}assertThat(ids).hasSize(n);}int size=t.matches.size();assertThat(SwissScheduler.advance(t)).isFalse();assertThat(t.matches).hasSize(size);}}
 @Test void bo3PauseFailureAndReviewBlockPairingUntilWholeSeriesComplete(){var t=cup(4,3);finish(t);assertThat(SwissScheduler.advance(t)).isFalse();TournamentSeries.advance(t);finish(t);var root=t.matches.getFirst();t.operations=t.operations.review(root.id,"review");assertThat(SwissScheduler.advance(t)).isFalse();t.operations=t.operations.review(root.id,null);t.status=TournamentStatus.PAUSED;assertThat(SwissScheduler.advance(t)).isFalse();t.status=TournamentStatus.RUNNING;t.matches.getLast().status=TournamentMatch.Status.FAILED;assertThat(SwissScheduler.advance(t)).isFalse();t.matches.getLast().status=TournamentMatch.Status.FINISHED;assertThat(SwissScheduler.advance(t)).isTrue();assertThat(t.swiss.currentRound()).isEqualTo(2);}
 @Test void buchholzSumsOpponentScoresAndByeGivesPointsWithoutFakeGames(){var t=cup(5,1);finish(t);var points=SwissScheduler.points(t);for(var p:t.participants){int expected=t.matches.stream().filter(m->Set.of(m.participantA.participantId(),m.participantB.participantId()).contains(p.participantId())).mapToInt(m->points.get(m.participantA.participantId().equals(p.participantId())?m.participantB.participantId():m.participantA.participantId())).sum();assertThat(SwissScheduler.buchholz(t,p.participantId())).isEqualTo(expected);}String bye=t.rounds.getFirst().byeParticipantIds().getFirst();var row=new RankingService(new ClassicScoringRule()).rank(t).stream().filter(r->r.participantId().equals(bye)).findFirst().orElseThrow();assertThat(row.points()).isEqualTo(3);assertThat(t.matches).hasSize(2);assertThat(row.wins()).isEqualTo(1);}
 @Test void restartKeepsPairingIdsAndInactivePlayersDoNotProduceFakeRepeatedGames(){var t=cup(6,1);finish(t);SwissScheduler.advance(t);var converter=new TournamentDetailsConverter();var details=converter.convertToEntityAttribute(converter.convertToDatabaseColumn(TournamentDetails.snapshot(t)));var restored=new Tournament(t.id,t.name,t.format,t.createdAt);restored.participants.addAll(t.participants);t.matches.forEach(m->restored.matches.add(m.copy()));details.restore(restored);restored.status=TournamentStatus.RUNNING;assertThat(restored.swiss).isEqualTo(t.swiss);assertThat(SwissScheduler.advance(restored)).isFalse();assertThat(restored.matches.stream().map(m->m.id)).containsExactlyElementsOf(t.matches.stream().map(m->m.id).toList());finish(t);for(var p:t.participants)t.operations=t.operations.participant(p.participantId(),ParticipantStatus.WITHDRAWN);assertThat(SwissScheduler.advance(t)).isTrue();assertThat(t.swiss.stopReason()).isEqualTo("INSUFFICIENT_ACTIVE_PLAYERS");}
 int brute(List<List<Integer>> g,int mask){if(mask==0)return 0;int first=Integer.numberOfTrailingZeros(mask),rest=mask&~(1<<first),best=brute(g,rest);for(int other:g.get(first))if((rest&(1<<other))!=0)best=Math.max(best,1+brute(g,rest&~(1<<other)));return best;}
 @Test void generalMatchingAgreesWithIndependentExhaustiveSearchIncludingOddCycles(){var random=new Random(20261016);for(int n=2;n<=10;n++)for(int sample=0;sample<60;sample++){var g=new ArrayList<List<Integer>>();for(int i=0;i<n;i++)g.add(new ArrayList<>());for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(random.nextBoolean()){g.get(i).add(j);g.get(j).add(i);}var result=new SwissMatching(g).solve();int count=0;for(int i=0;i<n;i++)if(result[i]>=0){assertThat(g.get(i)).contains(result[i]);assertThat(result[result[i]]).isEqualTo(i);count++;}assertThat(count/2).isEqualTo(brute(g,(1<<n)-1));}}
}
